"""The orders: what has shipped, fulfilling, invoices and the report."""

import datetime
import re
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Tuple

from .parsing import Movement, Order, Product
from .pricing import Quote, price_order
from .shelves import format_movement, in_date_order


@dataclass(frozen=True)
class Shipped:
    """Something with .lines that price_order can price."""

    lines: List[Tuple[str, int]]


@dataclass(frozen=True)
class FulfilLine:
    sku: str
    shipped: int
    backordered: int


@dataclass(frozen=True)
class FulfilResult:
    lines: List[FulfilLine]
    movements: List[str]
    status: str


@dataclass(frozen=True)
class ReportRow:
    order: Order
    status: str
    ordered: int
    shipped: int
    quoted: Quote
    invoiced: Optional[Quote]


def order_note(order_id: str) -> str:
    return "order {}".format(order_id)


def shipped_so_far(order: Order, movements: Iterable[Movement]) -> Dict[str, int]:
    """Units shipped per order line (capped at the quantity ordered)."""
    note = order_note(order.id)
    sent: Dict[str, int] = {sku: 0 for sku, _ in order.lines}
    for m in movements:
        if m.quantity < 0 and m.note == note and m.sku in sent:
            sent[m.sku] += -m.quantity
    return {sku: min(qty, sent[sku]) for sku, qty in order.lines}


def order_status(order: Order, shipped: Dict[str, int]) -> str:
    if all(shipped[sku] >= qty for sku, qty in order.lines):
        return "complete"
    if all(shipped[sku] == 0 for sku, _ in order.lines):
        return "open"
    return "partial"


def available_on(sku: str, date: datetime.date, movements: Iterable[Movement]) -> int:
    """How many units of sku can leave on date without any balance going negative."""
    balance = 0
    lowest_later: Optional[int] = None
    at_date: Optional[int] = None
    for m in in_date_order(movements):
        if m.sku != sku:
            continue
        if m.date > date and at_date is None:
            at_date = balance
        balance += m.quantity
        if m.date > date:
            lowest_later = balance if lowest_later is None else min(lowest_later, balance)
    if at_date is None:
        at_date = balance
    available = at_date if lowest_later is None else min(at_date, lowest_later)
    return max(0, available)


def fulfil(order: Order, date: datetime.date, movements: List[Movement]) -> FulfilResult:
    """Work out what can ship on date. The caller writes result.movements."""
    shipped = shipped_so_far(order, movements)
    lines: List[FulfilLine] = []
    new_movements: List[str] = []
    after: Dict[str, int] = {}
    for sku, qty in order.lines:
        owed = qty - shipped[sku]
        ship = min(owed, available_on(sku, date, movements))
        if ship > 0:
            new_movements.append(format_movement(date, sku, -ship, order_note(order.id)))
        after[sku] = shipped[sku] + ship
        lines.append(FulfilLine(sku=sku, shipped=ship, backordered=owed - ship))
    return FulfilResult(lines=lines, movements=new_movements, status=order_status(order, after))


def invoice(order: Order, catalog: Dict[str, Product], movements: Iterable[Movement]) -> Optional[Quote]:
    """Price what has shipped so far, or None when nothing has."""
    shipped = shipped_so_far(order, movements)
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    if not lines:
        return None
    return price_order(Shipped(lines=lines), catalog)


def order_sort_key(order: Order):
    number = int(re.sub(r"^[A-Z]+-", "", order.id))
    return (order.date, number, order.id)


def report(orders: Iterable[Order], catalog: Dict[str, Product], movements: List[Movement]) -> List[ReportRow]:
    rows = []
    for order in sorted(orders, key=order_sort_key):
        shipped = shipped_so_far(order, movements)
        rows.append(
            ReportRow(
                order=order,
                status=order_status(order, shipped),
                ordered=sum(qty for _, qty in order.lines),
                shipped=sum(shipped.values()),
                quoted=price_order(order, catalog),
                invoiced=invoice(order, catalog, movements),
            )
        )
    return rows
